<script setup>
import { computed, onMounted, ref } from 'vue'
import { useRouter } from 'vue-router'
import { AlertCircle, BadgeCheck, ChevronRight, Circle, Play, RefreshCw, Route, ShieldCheck, Waypoints } from '@lucide/vue'
import { createIntegrationJourney, getIntegrationJourneyWorkspace, recordIntegrationJourneyVisit } from '../api/competitionJourney'

const router=useRouter(),workspace=ref({organizations:[],runs:[]}),loading=ref(false),action=ref(''),error=ref(''),notice=ref('')
const organizationId=ref(''),learnerId=ref(''),selectedRunId=ref(localStorage.getItem('edumatrix_integration_journey_id')||'')
const run=computed(()=>workspace.value.runs.find(item=>item.id===selectedRunId.value)||null)
const organization=computed(()=>workspace.value.organizations.find(item=>item.id===organizationId.value)||null)
const learners=computed(()=>organization.value?.learners||[])
const nextStep=computed(()=>run.value?.steps.find(item=>!item.complete)||null)
function detail(e){const d=e?.detail;return d?.message||(typeof d==='string'?d:'')||e?.message||'操作失败'}
function applyContext(item){const c=item?.integration_context;if(!c)return;organizationId.value=c.organization_id||'';learnerId.value=c.learner_public_id||''}
async function load(){loading.value=true;error.value='';try{workspace.value=await getIntegrationJourneyWorkspace();if(selectedRunId.value&&!workspace.value.runs.some(item=>item.id===selectedRunId.value))selectedRunId.value='';if(!selectedRunId.value&&workspace.value.runs.length)selectedRunId.value=workspace.value.runs[0].id;if(run.value)applyContext(run.value);else{organizationId.value=workspace.value.organizations[0]?.id||'';learnerId.value=workspace.value.organizations[0]?.learners?.[0]?.public_id||''}if(selectedRunId.value)localStorage.setItem('edumatrix_integration_journey_id',selectedRunId.value)}catch(e){error.value=detail(e)}finally{loading.value=false}}
function chooseOrganization(){learnerId.value=learners.value[0]?.public_id||''}
async function create(){action.value='create';error.value='';try{const item=await createIntegrationJourney({organization_id:organizationId.value,learner_public_id:learnerId.value,run_key:`integration-judge-${Date.now()}`});selectedRunId.value=item.id;localStorage.setItem('edumatrix_integration_journey_id',item.id);notice.value='本地集成旅程已建立，合成组织、管理员和学员上下文已冻结';await load()}catch(e){error.value=detail(e)}finally{action.value=''}}
async function openStep(step){if(!run.value)return;action.value=step.key;error.value='';try{await recordIntegrationJourneyVisit(run.value.id,{step_key:step.key,route:step.route});await router.push({path:step.route,query:{journey:run.value.id,organization_id:run.value.integration_context.organization_id,learner_public_id:run.value.integration_context.learner_public_id,step:step.key}})}catch(e){error.value=detail(e)}finally{action.value=''}}
function selectRun(id){selectedRunId.value=id;localStorage.setItem('edumatrix_integration_journey_id',id);applyContext(workspace.value.runs.find(item=>item.id===id))}
onMounted(load)
</script>

<template><main class="journey" data-testid="integration-judge-journey"><header><div><p class="eyebrow"><Route :size="14"/> FC5 integration journey</p><h1>本地集成旅程</h1><p>模拟 SSO → HR / LMS 同步 → xAPI / Webhook → 故障 → 重试 → 对账。</p></div><button class="icon" aria-label="刷新本地集成旅程" title="刷新" @click="load"><RefreshCw :size="17"/></button></header>
<p v-if="error" class="notice error"><AlertCircle :size="15"/>{{error}}</p><p v-if="notice" class="notice ok"><BadgeCheck :size="15"/>{{notice}}</p><p v-if="loading" class="notice"><RefreshCw class="spin" :size="15"/>正在恢复本地集成旅程</p>
<section v-if="!loading&&workspace.truthfulness" class="truth"><ShieldCheck :size="18"/><div><strong>{{workspace.truthfulness.data_label}}</strong><span>{{workspace.truthfulness.certification_label}}；不发送外部网络；页面访问不计完成。</span></div></section>
<template v-if="!loading"><section class="toolbar"><label><span>冻结合成组织</span><select v-model="organizationId" @change="chooseOrganization"><option value="" disabled>请选择组织</option><option v-for="item in workspace.organizations" :key="item.id" :value="item.id">{{item.name}}</option></select></label><label><span>冻结合成学员</span><select v-model="learnerId" :disabled="!organizationId"><option value="" disabled>请选择学员</option><option v-for="item in learners" :key="item.public_id" :value="item.public_id">{{item.display_name}}</option></select></label><label v-if="workspace.runs.length"><span>历史运行</span><select :value="run?.id||''" @change="selectRun($event.target.value)"><option value="" disabled>请选择运行</option><option v-for="item in workspace.runs" :key="item.id" :value="item.id">{{item.status}} · {{item.progress.completed}}/6 · {{item.run_key}}</option></select></label><button class="primary" :disabled="Boolean(action)||!organizationId||!learnerId" @click="create"><Play :size="14"/>新建集成旅程</button></section>
<section v-if="!run" class="empty"><Waypoints :size="38"/><h2>尚未开始本地集成旅程</h2><p v-if="workspace.organizations.length">选择同一合成组织与学员，建立可刷新恢复的六步运行。</p><p v-else>当前管理员尚未加入可演示的合成组织。</p></section>
<template v-else><section class="context"><div><span>冻结组织</span><strong>{{run.integration_context?.organization_name}}</strong></div><div><span>冻结学员</span><strong>{{run.integration_context?.learner_display_name}}</strong></div><div><span>运行边界</span><strong>本地模拟 · 外部网络关闭</strong></div></section><section class="progress"><div><span>完成进度</span><strong>{{run.progress.completed}} / {{run.progress.total}}</strong></div><div class="bar"><i :style="{width:`${run.progress.percent}%`}"/></div><div><span>运行状态</span><strong>{{run.status==='completed'?'已完成':'进行中'}}</strong></div><button v-if="nextStep" class="primary" @click="openStep(nextStep)">继续：{{nextStep.label}}<ChevronRight :size="14"/></button><span v-else class="complete"><BadgeCheck :size="15"/>六步集成闭环完成</span></section>
<section class="steps"><article v-for="(step,index) in run.steps" :key="step.key" :class="{done:step.complete,next:nextStep?.key===step.key}"><div class="index"><BadgeCheck v-if="step.complete" :size="16"/><Circle v-else :size="16"/>{{index+1}}</div><div class="body"><span>{{step.key}}</span><strong>{{step.label}}</strong><p>{{step.purpose}}</p><small>{{step.summary}}</small><code v-if="step.evidence_id">{{step.evidence_id}}</code></div><button class="secondary" :disabled="Boolean(action)" @click="openStep(step)">{{step.complete?'查看证据':'进入工作台'}}<ChevronRight :size="14"/></button></article></section>
<section class="audit"><div><span>访问记录</span><strong>{{run.visits.length}}</strong></div><p>每一步只读取同一冻结组织和学员的正式持久化对象；故障要求七场景证据，重试要求同一死信显式恢复，对账必须发生在恢复之后。</p></section></template></template></main></template>

<style scoped>.journey{max-width:1240px;margin:auto;color:#20272a;padding:4px 2px 42px}.journey header{display:flex;justify-content:space-between;align-items:flex-start;padding:24px 2px 20px;border-bottom:1px solid #dce2e5}.journey h1{font-size:24px;margin:6px 0;letter-spacing:0}.journey header p:last-child{font-size:13px;color:#667177}.eyebrow{display:flex;align-items:center;gap:7px;color:#3f6659;font-size:10px;font-weight:750;text-transform:uppercase}.icon{width:36px;height:36px;display:grid;place-items:center;border:1px solid #d8dfe2;background:#fff;border-radius:7px}.notice{display:flex;align-items:center;gap:7px;padding:11px 14px;background:#f4f7f8;font-size:10px}.notice.error{background:#fff1ef;color:#963f35}.notice.ok{background:#eef8f1;color:#276046}.truth{display:flex;align-items:center;gap:10px;padding:12px 15px;background:#eef6f3;color:#31594d;border-bottom:1px solid #cddfd9}.truth div{display:flex;flex-wrap:wrap;gap:5px 14px}.truth strong{font-size:11px}.truth span{font-size:10px}.toolbar{display:grid;grid-template-columns:1.2fr 1fr 1.2fr auto;align-items:end;gap:12px;padding:16px 0;border-bottom:1px solid #dce2e5}.toolbar label{display:flex;flex-direction:column;gap:5px;min-width:0}.toolbar label span{font-size:8px;color:#748087}.toolbar select{height:36px;border:1px solid #d4dcdf;background:#fff;padding:0 9px;font-size:10px;min-width:0;width:100%}.primary,.secondary{display:inline-flex;align-items:center;justify-content:center;gap:6px;border:0;border-radius:6px;padding:9px 11px;font-size:10px;font-weight:650;cursor:pointer}.primary{background:#315e50;color:#fff}.primary:disabled,.secondary:disabled{opacity:.55;cursor:not-allowed}.secondary{background:#eaf3f0;color:#315e50}.context{display:grid;grid-template-columns:1.2fr 1fr 1fr;border-bottom:1px solid #dce2e5;background:#f8fbfa}.context div{display:flex;min-width:0;flex-direction:column;padding:12px 15px;border-right:1px solid #e2e8e6}.context span{font-size:8px;color:#748087}.context strong{font-size:10px;overflow-wrap:anywhere}.progress{display:grid;grid-template-columns:auto 1fr auto auto;align-items:center;gap:16px;padding:17px;background:#f4f8f7;border-bottom:1px solid #dce2e5}.progress>div:not(.bar){display:flex;flex-direction:column}.progress span{font-size:8px;color:#748087}.progress strong{font-size:13px}.bar{height:6px;background:#dce8e4;overflow:hidden}.bar i{display:block;height:100%;background:#447867}.complete{display:flex!important;align-items:center;gap:6px;color:#276046!important;font-size:10px!important}.steps{display:grid;grid-template-columns:1fr 1fr;gap:12px;padding:22px 0}.steps article{display:grid;grid-template-columns:auto 1fr auto;align-items:center;gap:12px;min-width:0;padding:15px;border:1px solid #dce2e5;background:#fff}.steps article.done{border-color:#bdd3c5;background:#f4faf6}.steps article.next{border-color:#83ad9f}.index{display:flex;flex-direction:column;align-items:center;gap:3px;color:#65747a;font-size:8px}.done .index{color:#276046}.body{display:flex;min-width:0;flex-direction:column}.body>span{font-size:7px;color:#417665}.body strong{font-size:12px}.body p{font-size:9px;color:#748087;margin:3px 0}.body small{font-size:8px;color:#5f7067}.body code{margin-top:4px;font-size:7px;color:#748087;overflow-wrap:anywhere}.audit{display:flex;align-items:center;gap:16px;padding:14px;border:1px solid #dce2e5;background:#f8fafb}.audit div{display:flex;flex-direction:column;min-width:70px}.audit span{font-size:8px;color:#748087}.audit strong{font-size:15px}.audit p{font-size:9px;color:#667177}.empty{min-height:340px;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;gap:9px;color:#748087}.empty h2{font-size:15px;color:#20272a}.empty p{font-size:10px}.spin{animation:spin 1s linear infinite}@keyframes spin{to{transform:rotate(360deg)}}@media(max-width:1000px){.toolbar{grid-template-columns:1fr 1fr}.toolbar .primary{width:100%}}@media(max-width:800px){.toolbar,.context,.progress,.steps{grid-template-columns:1fr}.progress .primary{width:100%}.steps article{grid-template-columns:auto 1fr}.steps article button{grid-column:1/-1;width:100%}.context div{border-right:0;border-bottom:1px solid #e2e8e6}.audit{align-items:flex-start;flex-direction:column}}@media(max-width:430px){.journey h1{font-size:21px}.truth{align-items:flex-start}.toolbar select{width:100%}}</style>
